### `cfg.go` — CHK dominators and the corrected dominance frontier
```go
package ssa

import "fmt"

// BlockID identifies a basic block.
type BlockID int

// StmtKind distinguishes a definition from a use.
type StmtKind uint8

const (
	DefStmt StmtKind = iota
	UseStmt
)

// Stmt is a single source-level event. Order inside a block matters:
// a use sees the value produced by the most recent definition on the
// fall-through path.
type Stmt struct {
	Kind StmtKind
	Var  string
}

// Block is a basic block of the source CFG. Phis are not stored here;
// they are attached to the SSA result.
type Block struct {
	ID    BlockID
	Name  string
	Stmts []Stmt
	Succs []BlockID
	Preds []BlockID
}

// Function is a source-level control-flow graph.
type Function struct {
	Blocks []*Block
	Entry  BlockID
}

func NewFunction(n int, entry BlockID) *Function {
	f := &Function{Entry: entry}
	f.Blocks = make([]*Block, n)
	for i := range f.Blocks {
		f.Blocks[i] = &Block{ID: BlockID(i), Name: fmt.Sprintf("B%d", i)}
	}
	return f
}

// AddEdge inserts a directed edge, ignoring duplicates. Duplicate edges
// would otherwise distort the predecessor count used by the dominance
// frontier algorithm.
func (f *Function) AddEdge(from, to BlockID) {
	for _, s := range f.Blocks[from].Succs {
		if s == to {
			return
		}
	}
	f.Blocks[from].Succs = append(f.Blocks[from].Succs, to)
	f.Blocks[to].Preds = append(f.Blocks[to].Preds, from)
}

func (f *Function) Def(b BlockID, v string) {
	f.Blocks[b].Stmts = append(f.Blocks[b].Stmts, Stmt{Kind: DefStmt, Var: v})
}

func (f *Function) Use(b BlockID, v string) {
	f.Blocks[b].Stmts = append(f.Blocks[b].Stmts, Stmt{Kind: UseStmt, Var: v})
}

// CFGInfo caches the control-flow analyses shared by SSA construction and
// verification.
type CFGInfo struct {
	F       *Function
	RPO     []BlockID // reverse postorder (only reachable blocks)
	Post    []BlockID
	IDom    []BlockID // IDom[entry] == entry; -1 for unreachable
	DomTree [][]BlockID
	DF      [][]BlockID // dominance frontier, indexed by block
	Reach   []bool
}

// Analyze runs DFS, the Cooper-Harvey-Kennedy dominator algorithm, and the
// Cytron dominance-frontier pass.
func Analyze(f *Function) *CFGInfo {
	info := &CFGInfo{F: f}
	info.RPO, info.Post, info.Reach = computeRPO(f)
	info.IDom = computeIDom(f, info.RPO, info.Reach)
	info.DomTree = buildDomTree(f, info.IDom, info.Reach)
	info.DF = computeDF(f, info.IDom, info.Reach)
	return info
}

func computeRPO(f *Function) (rpo, post []BlockID, reach []bool) {
	n := len(f.Blocks)
	reach = make([]bool, n)
	state := make([]uint8, n) // 0 unvisited, 1 on stack, 2 finished
	type frame struct {
		b BlockID
		i int
	}
	reach[f.Entry] = true
	state[f.Entry] = 1
	stack := []frame{{f.Entry, 0}}
	for len(stack) > 0 {
		fr := &stack[len(stack)-1]
		b := f.Blocks[fr.b]
		if fr.i < len(b.Succs) {
			s := b.Succs[fr.i]
			fr.i++
			if state[s] == 0 {
				state[s] = 1
				reach[s] = true
				stack = append(stack, frame{s, 0})
			}
			continue
		}
		post = append(post, fr.b)
		state[fr.b] = 2
		stack = stack[:len(stack)-1]
	}
	rpo = make([]BlockID, len(post))
	for i, b := range post {
		rpo[len(post)-1-i] = b
	}
	return
}

// computeIDom implements Cooper-Harvey-Kennedy: iterate the intersection of
// processed predecessors in reverse postorder until a fixed point. It works
// for reducible and irreducible graphs alike, and correctly handles a block
// that dominates itself (IDom[entry] == entry).
func computeIDom(f *Function, rpo []BlockID, reach []bool) []BlockID {
	n := len(f.Blocks)
	idom := make([]BlockID, n)
	rpoIndex := make([]int, n)
	for i := range idom {
		idom[i] = -1
		rpoIndex[i] = -1
	}
	for i, b := range rpo {
		rpoIndex[b] = i
	}
	idom[f.Entry] = f.Entry

	intersect := func(a, b BlockID) BlockID {
		for a != b {
			for rpoIndex[a] > rpoIndex[b] {
				a = idom[a]
			}
			for rpoIndex[b] > rpoIndex[a] {
				b = idom[b]
			}
		}
		return a
	}

	for changed := true; changed; {
		changed = false
		for _, b := range rpo {
			if b == f.Entry {
				continue
			}
			newIdom := BlockID(-1)
			for _, p := range f.Blocks[b].Preds {
				if idom[p] == -1 {
					continue // predecessor not processed yet
				}
				if newIdom == -1 {
					newIdom = p
				} else {
					newIdom = intersect(p, newIdom)
				}
			}
			if newIdom != -1 && idom[b] != newIdom {
				idom[b] = newIdom
				changed = true
			}
		}
	}
	return idom
}

func buildDomTree(f *Function, idom []BlockID, reach []bool) [][]BlockID {
	n := len(f.Blocks)
	tree := make([][]BlockID, n)
	for b := 0; b < n; b++ {
		if !reach[b] || BlockID(b) == f.Entry {
			continue
		}
		if idom[b] == -1 {
			continue
		}
		tree[idom[b]] = append(tree[idom[b]], BlockID(b))
	}
	return tree
}

// computeDF is the Cytron et al. dominance-frontier algorithm. For every
// join node b, walk up from each predecessor until reaching IDom[b].
//
// A block is always in its own dominance frontier when it has a self edge
// (b dominates the predecessor b, but does not strictly dominate itself),
// so self loops are handled explicitly. This matters for an entry block that
// jumps back to itself, whose single predecessor would otherwise be ignored
// by the usual |preds| >= 2 optimization.
func computeDF(f *Function, idom []BlockID, reach []bool) [][]BlockID {
	n := len(f.Blocks)
	df := make([][]BlockID, n)
	for b := 0; b < n; b++ {
		if !reach[b] {
			continue
		}
		blk := f.Blocks[b]
		if len(blk.Preds) == 0 {
			continue
		}
		idomB := idom[b]
		if BlockID(b) != f.Entry && len(blk.Preds) < 2 {
			continue
		}
		// If b is its own immediate dominator (the entry), b dominates every
		// predecessor and does not strictly dominate itself, so b is in its
		// own dominance frontier. The walk below cannot discover this
		// because it stops at IDom[b] == b.
		if BlockID(b) == f.Entry {
			df[b] = append(df[b], BlockID(b))
		}
		for _, p := range blk.Preds {
			runner := p
			for runner != idomB {
				if runner == -1 {
					break
				}
				if !containsBlock(df[runner], BlockID(b)) {
					df[runner] = append(df[runner], BlockID(b))
				}
				runner = idom[runner]
			}
		}
	}
	return df
}

func containsBlock(s []BlockID, b BlockID) bool {
	for _, x := range s {
		if x == b {
			return true
		}
	}
	return false
}

// Dominates reports whether a dominates b in the dominator tree.
// A block dominates itself, so Dominates(x, x) is always true.
func (info *CFGInfo) Dominates(a, b BlockID) bool {
	if a < 0 || b < 0 || !info.Reach[a] || !info.Reach[b] {
		return false
	}
	for {
		if b == a {
			return true
		}
		if b == info.F.Entry || info.IDom[b] == b {
			return false
		}
		b = info.IDom[b]
	}
}
```

### `ssa.go` — placement, renaming, pruning
```go
package ssa

// Value is an SSA name: either a phi result or a normal definition.
type Value struct {
	ID      int
	Var     string
	Block   BlockID
	IsPhi   bool
	Phi     *Phi
	DefStmt *Stmt // nil for phi values
}

// Phi is a phi function at the top of a block. Operands is indexed by the
// position of the incoming predecessor in Block.Preds.
type Phi struct {
	Var      string
	Block    BlockID
	Operands []*Value
	Value    *Value
	Removed  bool
}

// SSA is the constructed program.
type SSA struct {
	F      *Function
	Info   *CFGInfo
	Phis   [][]*Phi // phis per block
	Values []*Value

	UseVal map[*Stmt]*Value // source use  -> reaching SSA value
	DefVal map[*Stmt]*Value // source def  -> produced SSA value

	stacks map[string][]*Value
	nextID int
}

type renameState struct {
	s *SSA
}

func (s *SSA) newValue(varName string, b BlockID, isPhi bool, p *Phi, def *Stmt) *Value {
	v := &Value{ID: s.nextID, Var: varName, Block: b, IsPhi: isPhi, Phi: p, DefStmt: def}
	s.nextID++
	s.Values = append(s.Values, v)
	return v
}

func (s *SSA) push(varName string, v *Value) { s.stacks[varName] = append(s.stacks[varName], v) }

func (s *SSA) pop(varName string) {
	st := s.stacks[varName]
	if len(st) == 0 {
		return
	}
	s.stacks[varName] = st[:len(st)-1]
}

func (s *SSA) peek(varName string) *Value {
	st := s.stacks[varName]
	if len(st) == 0 {
		return nil
	}
	return st[len(st)-1]
}

// Build performs complete SSA construction:
//  1. CFG analysis (RPO, CHK immediate dominators, dominance frontier).
//  2. Minimal phi placement by iterating the dominance frontier of the
//     definition blocks of every variable.
//  3. Renaming via a dominator-tree walk with a per-variable value stack,
//     filling each phi operand from the predecessor's end-of-block value.
//  4. Pruning: trivial phis (a single distinct incoming definition) are
//     coalesced, and dead phis are removed until a fixed point.
func Build(f *Function) *SSA {
	info := Analyze(f)
	s := &SSA{
		F:      f,
		Info:   info,
		Phis:   make([][]*Phi, len(f.Blocks)),
		UseVal: map[*Stmt]*Value{},
		DefVal: map[*Stmt]*Value{},
	}
	s.placePhis()
	s.stacks = map[string][]*Value{}
	(&renameState{s: s}).run(f.Entry)
	s.prune()
	return s
}

// placePhis implements the Cytron "minimal SSA" placement using the
// iterated dominance frontier of each variable's definition blocks.
func (s *SSA) placePhis() {
	f := s.F
	defBlocks := map[string]map[BlockID]bool{}
	work := map[string][]BlockID{}
	for _, b := range f.Blocks {
		for i := range b.Stmts {
			if b.Stmts[i].Kind != DefStmt {
				continue
			}
			v := b.Stmts[i].Var
			if defBlocks[v] == nil {
				defBlocks[v] = map[BlockID]bool{}
			}
			if !defBlocks[v][b.ID] {
				defBlocks[v][b.ID] = true
				work[v] = append(work[v], b.ID)
			}
		}
	}
	hasPhi := map[string]map[BlockID]bool{}
	for v, wl := range work {
		hasPhi[v] = map[BlockID]bool{}
		for len(wl) > 0 {
			b := wl[0]
			wl = wl[1:]
			for _, d := range s.Info.DF[b] {
				if hasPhi[v][d] {
					continue
				}
				hasPhi[v][d] = true
				p := &Phi{Var: v, Block: d, Operands: make([]*Value, len(f.Blocks[d].Preds))}
				s.Phis[d] = append(s.Phis[d], p)
				if !defBlocks[v][d] {
					wl = append(wl, d)
				}
			}
		}
	}
}

func (r *renameState) run(entry BlockID) {
	r.rename(entry)
}

func (r *renameState) rename(b BlockID) {
	s := r.s
	f := s.F
	blk := f.Blocks[b]

	// 1. Phi results are defined at the top of the block.
	var pushed []string
	for _, p := range s.Phis[b] {
		v := s.newValue(p.Var, b, true, p, nil)
		p.Value = v
		s.push(p.Var, v)
		pushed = append(pushed, p.Var)
	}

	// 2. Walk the block in order: uses read, definitions write.
	for i := range blk.Stmts {
		st := &blk.Stmts[i]
		if st.Kind == UseStmt {
			s.UseVal[st] = s.peek(st.Var)
			continue
		}
		v := s.newValue(st.Var, b, false, nil, st)
		s.DefVal[st] = v
		s.push(st.Var, v)
		pushed = append(pushed, st.Var)
	}

	// 3. Fill successor phi operands from the value live at the end of b.
	//    This is what makes back-edge definitions into a loop header work.
	for _, sc := range blk.Succs {
		target := f.Blocks[sc]
		for _, p := range s.Phis[sc] {
			val := s.peek(p.Var)
			for pi, pred := range target.Preds {
				if pred == b {
					p.Operands[pi] = val
				}
			}
		}
	}

	// 4. Recurse over the dominator tree, then restore the stacks.
	for _, c := range s.Info.DomTree[b] {
		r.rename(c)
	}
	for i := len(pushed) - 1; i >= 0; i-- {
		s.pop(pushed[i])
	}
}

// prune eliminates redundant phi nodes to a fixed point:
//   - trivial phi: all non-self operands are the same value, so the phi is
//     replaced by that value;
//   - dead phi: the result is referenced by no use and no live phi operand.
func (s *SSA) prune() {
	for changed := true; changed; {
		changed = false

		// Trivial-phi coalescing.
		for _, phis := range s.Phis {
			for _, p := range phis {
				if p.Removed {
					continue
				}
				distinct := map[*Value]bool{}
				var only *Value
				for _, op := range p.Operands {
					if op == nil || op == p.Value {
						continue
					}
					distinct[op] = true
					only = op
				}
				if len(distinct) == 1 {
					s.replaceValue(p.Value, only)
					p.Removed = true
					changed = true
				}
			}
		}

		// Dead-phi elimination.
		used := map[*Value]bool{}
		for _, v := range s.UseVal {
			if v != nil {
				used[v] = true
			}
		}
		for _, phis := range s.Phis {
			for _, p := range phis {
				if p.Removed {
					continue
				}
				for _, op := range p.Operands {
					if op != nil {
						used[op] = true
					}
				}
			}
		}
		for _, phis := range s.Phis {
			for _, p := range phis {
				if p.Removed {
					continue
				}
				if !used[p.Value] {
					p.Removed = true
					changed = true
				}
			}
		}
	}
}

func (s *SSA) replaceValue(old, new *Value) {
	if old == new {
		return
	}
	for st, v := range s.UseVal {
		if v == old {
			s.UseVal[st] = new
		}
	}
	for _, phis := range s.Phis {
		for _, p := range phis {
			if p.Removed {
				continue
			}
			for i, op := range p.Operands {
				if op == old {
					p.Operands[i] = new
				}
			}
		}
	}
}
```

### `verify.go` — the independent verifier
The verifier recomputes, from the source CFG, a forward *reaching-definitions* analysis and a backward *liveness* analysis, then audits the constructed SSA. Brute-force dominators (`Dom[b] = {b} ∪ ∩ Dom[pred]`) and the set-theoretic frontier definition (`b ∈ DF(a)` iff `a` dominates some predecessor of `b` and does not strictly dominate `b`) are used as independent references.

Key oracle: for every SSA value `v`, `support(v)` is the fixpoint of source definition indices flowing into it (handles phi cycles). Then:
* `support(UseVal[use]) == defsOfVar(reaching(use), var)` — the use is bound to a value that represents **exactly** the reaching definitions, so no use can be missing a merge or carry an extra one;
* `support(phiOperand) == defsOfVar(OUT[pred], var)` and the operand's def dominates `pred`;
* surviving phis have ≥ 2 distinct non-self operands (not trivial), are referenced by a use or a live phi operand (not dead), and lie in the variable's iterated dominance frontier (placement valid).

```go
package ssa

import (
	"fmt"
	"sort"
	"strings"
)

// ---------------------------------------------------------------------------
// Independent source-level data-flow analyses used for verification.
// ---------------------------------------------------------------------------

type analysis struct {
	defIdx  map[*Stmt]int
	defVar  []string
	in, out []map[int]bool
	liveIn  []map[string]bool
	liveOut []map[string]bool
}

func newAnalysis(f *Function) *analysis {
	a := &analysis{defIdx: map[*Stmt]int{}}
	for _, b := range f.Blocks {
		for i := range b.Stmts {
			st := &b.Stmts[i]
			if st.Kind == DefStmt {
				a.defIdx[st] = len(a.defVar)
				a.defVar = append(a.defVar, st.Var)
			}
		}
	}
	n := len(f.Blocks)
	a.in = make([]map[int]bool, n)
	a.out = make([]map[int]bool, n)
	a.liveIn = make([]map[string]bool, n)
	a.liveOut = make([]map[string]bool, n)
	for i := 0; i < n; i++ {
		a.in[i] = map[int]bool{}
		a.out[i] = map[int]bool{}
		a.liveIn[i] = map[string]bool{}
		a.liveOut[i] = map[string]bool{}
	}
	a.computeReaching(f)
	a.computeLiveness(f)
	return a
}

// computeReaching is a standard forward may-definition analysis. The
// transfer function is applied statement by statement so that a definition
// kills an earlier definition of the same variable inside the block.
func (a *analysis) computeReaching(f *Function) {
	for changed := true; changed; {
		changed = false
		for _, b := range f.Blocks {
			ni := map[int]bool{}
			for _, p := range b.Preds {
				for d := range a.out[p] {
					ni[d] = true
				}
			}
			cur := copyIntSet(ni)
			for i := range b.Stmts {
				st := &b.Stmts[i]
				if st.Kind == DefStmt {
					for d := range cur {
						if a.defVar[d] == st.Var {
							delete(cur, d)
						}
					}
					cur[a.defIdx[st]] = true
				}
			}
			if !equalIntSet(ni, a.in[b.ID]) {
				a.in[b.ID] = ni
				changed = true
			}
			if !equalIntSet(cur, a.out[b.ID]) {
				a.out[b.ID] = cur
				changed = true
			}
		}
	}
}

// computeLiveness is a backward analysis. A variable is live-in to a block
// if it is used before being defined there, or live-out and not killed.
func (a *analysis) computeLiveness(f *Function) {
	for changed := true; changed; {
		changed = false
		for _, b := range f.Blocks {
			lo := map[string]bool{}
			for _, s := range b.Succs {
				for v := range a.liveIn[s] {
					lo[v] = true
				}
			}
			li := map[string]bool{}
			defined := map[string]bool{}
			for i := range b.Stmts {
				st := &b.Stmts[i]
				if st.Kind == UseStmt {
					if !defined[st.Var] {
						li[st.Var] = true
					}
				} else {
					defined[st.Var] = true
				}
			}
			for v := range lo {
				if !defined[v] {
					li[v] = true
				}
			}
			if !equalStrSet(lo, a.liveOut[b.ID]) {
				a.liveOut[b.ID] = lo
				changed = true
			}
			if !equalStrSet(li, a.liveIn[b.ID]) {
				a.liveIn[b.ID] = li
				changed = true
			}
		}
	}
}

// reachingAt walks a block and returns, for each use, the reaching set at
// the moment of the use. It is used to check the SSA binding.
func (a *analysis) reachingAt(f *Function, b *Block) []map[int]bool {
	res := make([]map[int]bool, len(b.Stmts))
	cur := copyIntSet(a.in[b.ID])
	for i := range b.Stmts {
		st := &b.Stmts[i]
		if st.Kind == UseStmt {
			res[i] = copyIntSet(cur)
		} else {
			for d := range cur {
				if a.defVar[d] == st.Var {
					delete(cur, d)
				}
			}
			cur[a.defIdx[st]] = true
		}
	}
	return res
}

// computeSupport computes, for every live SSA value, the set of source
// definition indices that flow into it. This is a fixpoint because phi
// operands can form cycles across loop back edges.
func (s *SSA) computeSupport(a *analysis) map[*Value]map[int]bool {
	sup := map[*Value]map[int]bool{}
	for _, v := range s.Values {
		if !v.IsPhi {
			sup[v] = map[int]bool{a.defIdx[v.DefStmt]: true}
		} else {
			sup[v] = map[int]bool{}
		}
	}
	for changed := true; changed; {
		changed = false
		for _, v := range s.Values {
			if !v.IsPhi || v.Phi == nil || v.Phi.Removed {
				continue
			}
			for _, op := range v.Phi.Operands {
				if op == nil {
					continue
				}
				for d := range sup[op] {
					if !sup[v][d] {
						sup[v][d] = true
						changed = true
					}
				}
			}
		}
	}
	return sup
}

// defsOfVar filters a reaching-definition set by variable name.
func (a *analysis) defsOfVar(set map[int]bool, name string) map[int]bool {
	res := map[int]bool{}
	for d := range set {
		if a.defVar[d] == name {
			res[d] = true
		}
	}
	return res
}

// ---------------------------------------------------------------------------
// Verifier
// ---------------------------------------------------------------------------

// Verify performs a full semantic and structural audit and returns all
// problems found (empty means the SSA program is valid, minimal and pruned).
func (s *SSA) Verify() []string {
	var errs []string
	add := func(format string, args ...any) {
		errs = append(errs, fmt.Sprintf(format, args...))
	}
	f := s.F
	info := s.Info
	a := newAnalysis(f)

	// --- 1. Immediate dominators against a brute-force data-flow solution.
	bidom := bruteIDom(f, info.Reach)
	for b := range f.Blocks {
		if !info.Reach[b] {
			continue
		}
		if BlockID(b) == f.Entry {
			if info.IDom[b] != f.Entry {
				add("idom[entry]=%d, want %d (entry dominates itself)", info.IDom[b], f.Entry)
			}
			continue
		}
		if info.IDom[b] != bidom[b] {
			add("idom[B%d]=%d, brute-force=%d", b, info.IDom[b], bidom[b])
		}
	}

	// --- 2. Dominance frontier against the set-theoretic definition.
	bdf := bruteDF(f, info.IDom, bruteDom(f, info.Reach), info.Reach)
	for b := range f.Blocks {
		if !info.Reach[b] {
			continue
		}
		if !equalBlockSet(toBlockSet(info.DF[b]), bdf[b]) {
			add("DF[B%d]=%v, brute-force=%v", b, sortBlocks(info.DF[b]), sortBlocks(blockSetSlice(bdf[b])))
		}
	}

	// --- 3. Every use is bound to exactly one value whose support is
	//        exactly the set of source definitions reaching that use.
	sup := s.computeSupport(a)
	idf := s.idfOracle(a)
	for _, b := range f.Blocks {
		if !info.Reach[b.ID] {
			continue
		}
		reaching := a.reachingAt(f, b)
		for i := range b.Stmts {
			st := &b.Stmts[i]
			if st.Kind != UseStmt {
				continue
			}
			v := s.UseVal[st]
			if v == nil {
				add("unbound use of %s in %s", st.Var, b.Name)
				continue
			}
			if v.Var != st.Var {
				add("use of %s in %s bound to value of %s", st.Var, b.Name, v.Var)
			}
			if !equalIntSet(sup[v], a.defsOfVar(reaching[i], st.Var)) {
				add("use of %s in %s: support %v != reaching %v", st.Var, b.Name,
					intSetSlice(sup[v]), intSetSlice(a.defsOfVar(reaching[i], st.Var)))
			}
			if v.IsPhi {
				if !info.Dominates(v.Block, b.ID) {
					add("use of %s in %s uses phi from non-dominating %s", st.Var, b.Name, f.Blocks[v.Block].Name)
				}
			} else {
				if v.Block == b.ID {
					defPos := stmtIndex(b, v.DefStmt)
					if defPos < 0 || defPos >= i {
						add("use of %s in %s precedes its definition", st.Var, b.Name)
					}
				} else if !info.Dominates(v.Block, b.ID) {
					add("use of %s in %s uses def from non-dominating %s", st.Var, b.Name, f.Blocks[v.Block].Name)
				}
			}
		}
	}

	// --- 4. Phi operands: one per predecessor, dominating it, and carrying
	//        exactly the definitions reaching the predecessor's end.
	used := map[*Value]bool{}
	for _, v := range s.UseVal {
		if v != nil {
			used[v] = true
		}
	}
	for _, phis := range s.Phis {
		for _, p := range phis {
			if !p.Removed {
				for _, op := range p.Operands {
					if op != nil {
						used[op] = true
					}
				}
			}
		}
	}
	for _, b := range f.Blocks {
		for _, p := range s.Phis[b.ID] {
			if p.Removed {
				continue
			}
			blk := f.Blocks[p.Block]
			if len(p.Operands) != len(blk.Preds) {
				add("phi %s in %s has %d operands for %d preds", p.Var, blk.Name, len(p.Operands), len(blk.Preds))
			}
			distinct := map[*Value]bool{}
			for pi, pred := range blk.Preds {
				var op *Value
				if pi < len(p.Operands) {
					op = p.Operands[pi]
				}
				if op == nil {
					add("phi %s in %s has nil operand from %s", p.Var, blk.Name, f.Blocks[pred].Name)
					continue
				}
				if op.Var != p.Var {
					add("phi %s in %s operand from %s has var %s", p.Var, blk.Name, f.Blocks[pred].Name, op.Var)
				}
				if op != p.Value {
					distinct[op] = true
				}
				if !info.Dominates(op.Block, pred) {
					add("phi %s in %s operand from %s not dominated by its def in %s",
						p.Var, blk.Name, f.Blocks[pred].Name, f.Blocks[op.Block].Name)
				}
				want := a.defsOfVar(a.out[pred], p.Var)
				if !equalIntSet(sup[op], want) {
					add("phi %s in %s operand from %s: support %v != reaching-end %v",
						p.Var, blk.Name, f.Blocks[pred].Name, intSetSlice(sup[op]), intSetSlice(want))
				}
			}
			// --- 5. No trivial phi survives: at least two distinct
			//        non-self incoming values are required.
			if len(distinct) < 2 {
				add("trivial phi survived: %s in %s (%d distinct operands)", p.Var, blk.Name, len(distinct))
			}
			// --- 6. No dead phi survives.
			if !used[p.Value] {
				add("dead phi survived: %s in %s", p.Var, blk.Name)
			}
			// --- 7. Minimality: every phi lies in the iterated dominance
			//        frontier of the variable's definitions.
			if !idf[p.Var][p.Block] {
				add("phi %s in %s is outside IDF of its defs", p.Var, blk.Name)
			}
		}
	}
	return errs
}

func stmtIndex(b *Block, st *Stmt) int {
	for i := range b.Stmts {
		if &b.Stmts[i] == st {
			return i
		}
	}
	return -1
}

// idfOracle recomputes iterated dominance frontiers for every variable.
func (s *SSA) idfOracle(a *analysis) map[string]map[BlockID]bool {
	defBlocks := map[string]map[BlockID]bool{}
	for _, b := range s.F.Blocks {
		for i := range b.Stmts {
			if b.Stmts[i].Kind != DefStmt {
				continue
			}
			v := b.Stmts[i].Var
			if defBlocks[v] == nil {
				defBlocks[v] = map[BlockID]bool{}
			}
			defBlocks[v][b.ID] = true
		}
	}
	res := map[string]map[BlockID]bool{}
	for v, defs := range defBlocks {
		idf := map[BlockID]bool{}
		queue := make([]BlockID, 0, len(defs))
		for d := range defs {
			queue = append(queue, d)
		}
		for len(queue) > 0 {
			b := queue[0]
			queue = queue[1:]
			for _, d := range s.Info.DF[b] {
				if !idf[d] {
					idf[d] = true
					queue = append(queue, d)
				}
			}
		}
		res[v] = idf
	}
	return res
}

// ---------------------------------------------------------------------------
// Brute-force reference implementations (only used above).
// ---------------------------------------------------------------------------

func bruteDom(f *Function, reach []bool) []map[BlockID]bool {
	n := len(f.Blocks)
	all := map[BlockID]bool{}
	for i := 0; i < n; i++ {
		all[BlockID(i)] = true
	}
	dom := make([]map[BlockID]bool, n)
	for i := 0; i < n; i++ {
		if BlockID(i) == f.Entry {
			dom[i] = map[BlockID]bool{f.Entry: true}
		} else {
			dom[i] = copyBlockSet(all)
		}
	}
	for changed := true; changed; {
		changed = false
		for _, b := range f.Blocks {
			if b.ID == f.Entry {
				continue
			}
			var nd map[BlockID]bool
			first := true
			for _, p := range b.Preds {
				if !reach[p] {
					continue
				}
				if first {
					nd = copyBlockSet(dom[p])
					first = false
				} else {
					intersectBlockSet(nd, dom[p])
				}
			}
			if nd == nil {
				continue
			}
			nd[b.ID] = true
			if !equalBlockSet(nd, dom[b.ID]) {
				dom[b.ID] = nd
				changed = true
			}
		}
	}
	return dom
}

func bruteIDom(f *Function, reach []bool) []BlockID {
	dom := bruteDom(f, reach)
	n := len(f.Blocks)
	idom := make([]BlockID, n)
	for i := 0; i < n; i++ {
		idom[i] = -1
	}
	idom[f.Entry] = f.Entry
	for b := 0; b < n; b++ {
		if !reach[b] || BlockID(b) == f.Entry {
			continue
		}
		// The immediate dominator is the unique proper dominator that is
		// dominated by every other proper dominator.
		for d := range dom[b] {
			if d == BlockID(b) {
				continue
			}
			ok := true
			for x := range dom[b] {
				if x == BlockID(b) || x == d {
					continue
				}
				if !dom[d][x] { // x must dominate d
					ok = false
					break
				}
			}
			if ok {
				idom[b] = d
				break
			}
		}
	}
	return idom
}

// bruteDF computes DF from the set-theoretic definition using the full
// dominator sets, independently of the Cytron walk-up algorithm.
func bruteDF(f *Function, idom []BlockID, dom []map[BlockID]bool, reach []bool) []map[BlockID]bool {
	n := len(f.Blocks)
	df := make([]map[BlockID]bool, n)
	for i := 0; i < n; i++ {
		df[i] = map[BlockID]bool{}
	}
	for b := 0; b < n; b++ {
		if !reach[b] {
			continue
		}
		for a := 0; a < n; a++ {
			if !reach[a] {
				continue
			}
			strictDom := BlockID(a) != BlockID(b) && dom[b][BlockID(a)]
			if strictDom {
				continue
			}
			for _, p := range f.Blocks[b].Preds {
				if !reach[p] {
					continue
				}
				if dom[p][BlockID(a)] {
					df[a][BlockID(b)] = true
					break
				}
			}
		}
	}
	return df
}

// ---------------------------------------------------------------------------
// Small set helpers.
// ---------------------------------------------------------------------------

func copyIntSet(m map[int]bool) map[int]bool {
	r := make(map[int]bool, len(m))
	for k := range m {
		r[k] = true
	}
	return r
}

func equalIntSet(a, b map[int]bool) bool {
	if len(a) != len(b) {
		return false
	}
	for k := range a {
		if !b[k] {
			return false
		}
	}
	return true
}

func equalStrSet(a, b map[string]bool) bool {
	if len(a) != len(b) {
		return false
	}
	for k := range a {
		if !b[k] {
			return false
		}
	}
	return true
}

func copyBlockSet(m map[BlockID]bool) map[BlockID]bool {
	r := make(map[BlockID]bool, len(m))
	for k := range m {
		r[k] = true
	}
	return r
}

func equalBlockSet(a, b map[BlockID]bool) bool {
	if len(a) != len(b) {
		return false
	}
	for k := range a {
		if !b[k] {
			return false
		}
	}
	return true
}

func intersectBlockSet(a, b map[BlockID]bool) {
	for k := range a {
		if !b[k] {
			delete(a, k)
		}
	}
}

func toBlockSet(s []BlockID) map[BlockID]bool {
	r := map[BlockID]bool{}
	for _, b := range s {
		r[b] = true
	}
	return r
}

func blockSetSlice(m map[BlockID]bool) []BlockID {
	r := make([]BlockID, 0, len(m))
	for b := range m {
		r = append(r, b)
	}
	return r
}

func sortBlocks(s []BlockID) []BlockID {
	r := append([]BlockID(nil), s...)
	sort.Slice(r, func(i, j int) bool { return r[i] < r[j] })
	return r
}

func intSetSlice(m map[int]bool) []int {
	r := make([]int, 0, len(m))
	for k := range m {
		r = append(r, k)
	}
	sort.Ints(r)
	return r
}

// Format renders the constructed SSA program for debugging and golden tests.
func (s *SSA) Format() string {
	var sb strings.Builder
	for _, b := range s.F.Blocks {
		sb.WriteString(b.Name)
		sb.WriteString(":\n")
		for _, p := range s.Phis[b.ID] {
			if p.Removed {
				continue
			}
			fmt.Fprintf(&sb, "  %s = phi(", p.Var)
			for i, op := range p.Operands {
				if i > 0 {
					sb.WriteString(", ")
				}
				if op == nil {
					sb.WriteString("<nil>")
				} else {
					fmt.Fprintf(&sb, "v%d", op.ID)
				}
			}
			sb.WriteString(")\n")
		}
		for i := range b.Stmts {
			st := &b.Stmts[i]
			if st.Kind == DefStmt {
				if v := s.DefVal[st]; v != nil {
					fmt.Fprintf(&sb, "  v%d = define %s\n", v.ID, st.Var)
				}
			} else {
				if v := s.UseVal[st]; v != nil {
					fmt.Fprintf(&sb, "  use %s (v%d)\n", st.Var, v.ID)
				} else {
					fmt.Fprintf(&sb, "  use %s (<nil>)\n", st.Var)
				}
			}
		}
	}
	return sb.String()
}
