### `ssa_test.go` — 10 tests over hand-built and random CFGs
The nine deterministic CFGs are: straight line, diamond, loop with preheader + back-edge def, nested loops, **2-entry irreducible loop**, self-loop, dead-phi, forced trivial-phi coalescing, and an irreducible dominator cross-check. The tenth is a 3000-iteration randomized differential stress test (a 50 000-iteration and a 20-block/4-variable run were also used during development and passed).

```go
package ssa

import (
	"sort"
	"strings"
	"testing"
)

// buildCheck builds SSA, runs the full verifier, and compares the surviving
// phi set against the hand-derived expectation.
func buildCheck(t *testing.T, f *Function, want map[string][]BlockID) *SSA {
	t.Helper()
	s := Build(f)
	if errs := s.Verify(); len(errs) > 0 {
		t.Fatalf("verification failed:\n  %s\nSSA:\n%s", strings.Join(errs, "\n  "), s.Format())
	}
	got := map[string][]BlockID{}
	for _, b := range f.Blocks {
		for _, p := range s.Phis[b.ID] {
			if !p.Removed {
				got[p.Var] = append(got[p.Var], b.ID)
			}
		}
	}
	for v, bs := range want {
		if !sameBlocks(got[v], bs) {
			t.Errorf("phi blocks for %q = %v, want %v", v, got[v], bs)
		}
	}
	for v := range got {
		if _, ok := want[v]; !ok {
			t.Errorf("unexpected phi for %q at %v", v, got[v])
		}
	}
	return s
}

func sameBlocks(a, b []BlockID) bool {
	if len(a) != len(b) {
		return false
	}
	aa := append([]BlockID(nil), a...)
	bb := append([]BlockID(nil), b...)
	sort.Slice(aa, func(i, j int) bool { return aa[i] < aa[j] })
	sort.Slice(bb, func(i, j int) bool { return bb[i] < bb[j] })
	for i := range aa {
		if aa[i] != bb[i] {
			return false
		}
	}
	return true
}

// 1. Straight-line code: a definition dominates every use, so no phi.
func TestStraightLine(t *testing.T) {
	f := NewFunction(3, 0)
	f.Def(0, "x")
	f.Use(1, "x")
	f.Use(2, "x")
	f.AddEdge(0, 1)
	f.AddEdge(1, 2)
	buildCheck(t, f, map[string][]BlockID{})
}

// 2. Reducible diamond: each join of two distinct definitions needs a phi.
func TestDiamond(t *testing.T) {
	f := NewFunction(5, 0)
	f.Def(0, "x")
	f.Def(0, "y")
	f.Def(1, "x")
	f.Def(2, "y")
	f.Use(3, "x")
	f.Use(3, "y")
	f.Use(4, "x")
	f.Use(4, "y")
	f.AddEdge(0, 1)
	f.AddEdge(0, 2)
	f.AddEdge(1, 3)
	f.AddEdge(2, 3)
	f.AddEdge(3, 4)
	buildCheck(t, f, map[string][]BlockID{"x": {3}, "y": {3}})
}

// 3. Loop with a preheader definition plus a definition on the back edge.
// The header use must read a phi; the definition living on the back edge
// arrives "before the preheader" is processed by a naive renaming walk.
func TestLoopBackEdge(t *testing.T) {
	f := NewFunction(5, 0)
	f.Def(0, "x") // preheader definition
	f.Use(1, "x") // loop condition
	f.Def(2, "x") // back-edge definition
	f.Use(3, "x")
	f.AddEdge(0, 1)
	f.AddEdge(1, 2)
	f.AddEdge(1, 3)
	f.AddEdge(2, 1) // back edge into header
	f.AddEdge(3, 4)
	buildCheck(t, f, map[string][]BlockID{"x": {1}})
}

// 4. Nested loops: both headers require phis for both loop-carried vars.
func TestNestedLoops(t *testing.T) {
	f := NewFunction(7, 0)
	f.Def(0, "x")
	f.Def(0, "y")
	f.Use(1, "x")
	f.Use(1, "y")
	f.Use(2, "x")
	f.Use(2, "y")
	f.Def(3, "x")
	f.Def(3, "y")
	f.Use(4, "x")
	f.Use(4, "y")
	f.Use(5, "x")
	f.Use(5, "y")
	f.AddEdge(0, 1)
	f.AddEdge(1, 2) // enter inner
	f.AddEdge(1, 5) // leave outer
	f.AddEdge(2, 3) // inner body
	f.AddEdge(2, 4) // leave inner
	f.AddEdge(3, 2) // inner back edge
	f.AddEdge(4, 1) // outer back edge
	f.AddEdge(5, 6)
	buildCheck(t, f, map[string][]BlockID{"x": {1, 2}, "y": {1, 2}})
}

// 5. Two-entry irreducible loop. B1 and B2 are both headers entered from
// the preheader and from each other, so neither dominates the other and both
// need phis; B3 is the shared exit join.
func TestIrreducibleTwoEntry(t *testing.T) {
	f := NewFunction(5, 0)
	f.Def(0, "v")
	f.Use(1, "v")
	f.Def(1, "v")
	f.Use(2, "v")
	f.Def(2, "v")
	f.Use(3, "v")
	f.AddEdge(0, 1)
	f.AddEdge(0, 2)
	f.AddEdge(1, 2)
	f.AddEdge(1, 3)
	f.AddEdge(2, 1)
	f.AddEdge(2, 3)
	f.AddEdge(3, 4)
	buildCheck(t, f, map[string][]BlockID{"v": {1, 2, 3}})
}

// 6. Self-loop: DF[B1] contains B1 itself, exercising a block that
// dominates itself and a self-referential back edge.
func TestSelfLoop(t *testing.T) {
	f := NewFunction(4, 0)
	f.Def(0, "x")
	f.Use(1, "x")
	f.Def(1, "x")
	f.Use(2, "x")
	f.AddEdge(0, 1)
	f.AddEdge(1, 1) // self loop
	f.AddEdge(1, 2)
	f.AddEdge(2, 3)
	buildCheck(t, f, map[string][]BlockID{"x": {1}})
}

// 7. A phi is placed by the IDF algorithm even though x is dead; the
// dead-phi pass must remove it, leaving a clean program.
func TestDeadPhiRemoved(t *testing.T) {
	f := NewFunction(6, 0)
	f.Def(0, "z")
	f.Def(1, "x")
	f.Def(2, "x")
	f.Use(4, "z")
	f.AddEdge(0, 1)
	f.AddEdge(0, 2)
	f.AddEdge(1, 3)
	f.AddEdge(2, 3)
	f.AddEdge(3, 4)
	f.AddEdge(4, 5)

	s := Build(f)
	// The IDF algorithm must have proposed a phi before pruning...
	proposed := false
	for _, p := range s.Phis[3] {
		if p.Var == "x" {
			proposed = true
		}
	}
	if !proposed {
		t.Fatalf("expected phi for dead x to be proposed at B3")
	}
	// ...and the verifier must accept the pruned result with no phis.
	if errs := s.Verify(); len(errs) > 0 {
		t.Fatalf("verification failed: %s", strings.Join(errs, "\n"))
	}
	for _, b := range f.Blocks {
		for _, p := range s.Phis[b.ID] {
			if !p.Removed {
				t.Errorf("dead phi survived at %s for %s", b.Name, p.Var)
			}
		}
	}
}

// 8. Direct unit test of trivial-phi coalescing: force a phi whose incoming
// values are all the same, prune, and confirm it is removed and its uses are
// rewired to the single definition.
func TestTrivialPhiPruned(t *testing.T) {
	f := NewFunction(5, 0)
	f.Def(0, "x")
	f.Use(1, "x")
	f.Def(2, "x")
	f.Use(3, "x")
	f.AddEdge(0, 1)
	f.AddEdge(1, 2)
	f.AddEdge(1, 3)
	f.AddEdge(2, 1)
	f.AddEdge(3, 4)

	s := Build(f)
	var ph *Phi
	for _, p := range s.Phis[1] {
		if p.Var == "x" {
			ph = p
		}
	}
	if ph == nil {
		t.Fatal("expected a phi at B1")
	}
	// Make every incoming operand identical.
	same := ph.Operands[0]
	for i := range ph.Operands {
		ph.Operands[i] = same
	}
	s.prune()
	if !ph.Removed {
		t.Fatalf("trivial phi was not removed")
	}
	for st, v := range s.UseVal {
		if v == ph.Value {
			t.Errorf("use %v still references removed trivial phi", st)
		}
	}
}

// 9. The CHK dominator algorithm and the brute-force data-flow dominators
// agree on an irreducible graph; also confirm a block dominates itself.
func TestDominatorsIrreducible(t *testing.T) {
	f := NewFunction(5, 0)
	f.AddEdge(0, 1)
	f.AddEdge(0, 2)
	f.AddEdge(1, 2)
	f.AddEdge(1, 3)
	f.AddEdge(2, 1)
	f.AddEdge(2, 3)
	f.AddEdge(3, 4)
	info := Analyze(f)
	bf := bruteIDom(f, info.Reach)
	for b := range f.Blocks {
		if !info.Reach[b] {
			continue
		}
		if info.IDom[b] != bf[b] {
			t.Fatalf("idom[B%d] = %d, brute force = %d", b, info.IDom[b], bf[b])
		}
	}
	if info.IDom[0] != 0 {
		t.Fatalf("entry must dominate itself")
	}
	if !info.Dominates(1, 1) || !info.Dominates(2, 2) {
		t.Fatalf("block must dominate itself")
	}
	if info.Dominates(1, 2) || info.Dominates(2, 1) {
		t.Fatalf("neither irreducible header may dominate the other")
	}
}

// 10. Randomized differential stress test. Every variable is defined in the
// entry block first, so programs are well-formed; extra random edges can
// create irreducible loops. The full verifier must accept every result.
func TestRandomCFGs(t *testing.T) {
	rng := newRNG(0xC0FFEE)
	vars := []string{"x", "y", "z"}
	for iter := 0; iter < 3000; iter++ {
		n := 1 + int(rng()%8)
		f := NewFunction(n, 0)
		// Guarantee reachability with a random in-tree, then add extra edges.
		for i := 1; i < n; i++ {
			f.AddEdge(BlockID(rng()%uint64(i)), BlockID(i))
		}
		extra := int(rng() % uint64(2*n+1))
		for k := 0; k < extra; k++ {
			a := BlockID(rng() % uint64(n))
			b := BlockID(rng() % uint64(n))
			f.AddEdge(a, b)
		}
		// Entry definitions make all variables well-defined everywhere.
		for _, v := range vars {
			f.Def(0, v)
		}
		for b := 0; b < n; b++ {
			events := int(rng() % 4)
			for k := 0; k < events; k++ {
				v := vars[rng()%uint64(len(vars))]
				if rng()%2 == 0 {
					f.Def(BlockID(b), v)
				} else {
					f.Use(BlockID(b), v)
				}
			}
		}
		s := Build(f)
		if errs := s.Verify(); len(errs) > 0 {
			t.Fatalf("iter %d: verification failed:\n  %s\nSSA:\n%s", iter, strings.Join(errs, "\n  "), s.Format())
		}
	}
}

// tiny deterministic xorshift PRNG so the stress test is reproducible.
type rngState struct{ s uint64 }

func newRNG(seed uint64) func() uint64 {
	r := &rngState{s: seed}
	return func() uint64 {
		r.s ^= r.s << 13
		r.s ^= r.s >> 7
		r.s ^= r.s << 17
		return r.s
	}
}
